// Простейший поиск по названию (доступен глобально)
function searchFoodDB(query) {
  const q = query.toLowerCase().trim();
  if (q.length < 2) return [];
  return FOOD_DB.filter(item =>
    item.n.toLowerCase().includes(q)
  ).slice(0, 20);
}